  /**
   * @method
   * @name lbank#fetchTime
   * @description fetches the current integer timestamp in milliseconds from the
   * exchange server
   * @see https://www.lbank.com/en-US/docs/index.html#get-timestamp
   * @see https://www.lbank.com/en-US/docs/contract.html#get-the-current-time
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int} the current integer timestamp in milliseconds from the
   * exchange server
   */
  std::shared_future<std::any>
  fetchTime(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any type = std::any{};
                 std::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("fetchTime"), std::any{}, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(isEqual(type, std::string("swap")))) {
                   response = awaitValue(
                       this->contractPublicGetCfdOpenApiV1PubGetTime(params));
                 } else {
                   response = awaitValue(this->spotPublicGetTimestamp(params));
                 }
                 //
                 // spot
                 //
                 //     {
                 //         "result": "true",
                 //         "data": 1691789627950,
                 //         "error_code": 0,
                 //         "ts": 1691789627950
                 //     }
                 //
                 // swap
                 //
                 //     {
                 //         "data": 1691789627950,
                 //         "error_code": 0,
                 //         "msg": "Success",
                 //         "result": "true",
                 //         "success": true
                 //     }
                 //
                 return this->safeInteger(response, std::string("data"));
               })
        .share();
  }

  /**
   * @method
   * @name lbank#fetchCurrencies
   * @description fetches all available currencies on an exchange
   * @param {dict} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {dict} an associative dictionary of currencies
   */
  std::shared_future<std::any>
  fetchCurrencies(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any response = awaitValue(
                            this->spotPublicGetWithdrawConfigs(params));
                        //
                        //    {
                        //        "msg": "Success",
                        //        "result": "true",
                        //        "data": [
                        //            {
                        //                "amountScale": "4",
                        //                "chain": "bep20(bsc)",
                        //                "assetCode": "usdt",
                        //                "min": "10",
                        //                "transferAmtScale": "4",
                        //                "canWithDraw": true,
                        //                "fee": "0.0000",
                        //                "minTransfer": "0.0001",
                        //                "type": "1"
                        //            },
                        //            {
                        //                "amountScale": "4",
                        //                "chain": "trc20",
                        //                "assetCode": "usdt",
                        //                "min": "1",
                        //                "transferAmtScale": "4",
                        //                "canWithDraw": true,
                        //                "fee": "1.0000",
                        //                "minTransfer": "0.0001",
                        //                "type": "1"
                        //            },
                        //            ...
                        //        ],
                        //        "error_code": "0",
                        //        "ts": "1747973911431"
                        //    }
                        //
                        std::any currenciesData = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        std::any grouped = this->groupBy(
                            currenciesData, std::string("assetCode"));
                        std::any values = getObjectValues(grouped);
                        return this->parseCurrencies(values);
                      })
        .share();
  }

  std::any parseCurrency(std::any rawCurrency) override {
    std::any id = this->safeString(
        ::getValue(rawCurrency, 0),
        std::string("assetCode")); // first member is guaranteed
    std::any code = this->safeCurrencyCode(id);
    std::any networksRaw = rawCurrency;
    std::any networks = ccxt::dict{};
    for (std::any j = 0; isLessThan(j, getArrayLength(networksRaw));
         postFixIncrement(j)) {
      std::any networkEntry = ::getValue(networksRaw, j);
      std::any networkId = this->safeString(networkEntry, std::string("chain"));
      if (isTrue(isEqual(networkId, std::any{}))) {
        networkId = this->safeString(
            networkEntry, std::string("assetCode")); // use type as fallback if
                                                     // networkId is not present
      }
      std::any networkCode = this->networkIdToCode(networkId, code);
      if (isTrue(!isEqual(networkCode, std::any{}))) {
        ::setValue(
            networks, networkCode,
            ccxt::dict{
                {std::string("id"), networkId},
                {std::string("network"), networkCode},
                {std::string("limits"),
                 ccxt::dict{
                     {std::string("withdraw"),
                      ccxt::dict{
                          {std::string("min"),
                           this->safeNumber(networkEntry, std::string("min"))},
                          {std::string("max"), std::any{}},
                      }},
                     {std::string("deposit"),
                      ccxt::dict{
                          {std::string("min"),
                           this->safeNumber(networkEntry,
                                            std::string("minTransfer"))},
                          {std::string("max"), std::any{}},
                      }},
                 }},
                {std::string("active"), std::any{}},
                {std::string("deposit"), std::any{}},
                {std::string("withdraw"),
                 this->safeBool(networkEntry, std::string("canWithDraw"))},
                {std::string("fee"),
                 this->safeNumber(networkEntry, std::string("fee"))},
                {std::string("precision"),
                 this->parseNumber(this->parsePrecision(this->safeString(
                     networkEntry, std::string("transferAmtScale"))))},
                {std::string("info"), networkEntry},
            });
      }
    }
    return this->safeCurrencyStructure(ccxt::dict{
        {std::string("id"), id},
        {std::string("code"), code},
        {std::string("precision"), std::any{}},
        {std::string("type"), std::any{}},
        {std::string("name"), std::any{}},
        {std::string("active"), std::any{}},
        {std::string("deposit"), std::any{}},
        {std::string("withdraw"), std::any{}},
        {std::string("fee"), std::any{}},
        {std::string("limits"),
         ccxt::dict{
             {std::string("withdraw"),
              ccxt::dict{
                  {std::string("min"), std::any{}},
                  {std::string("max"), std::any{}},
              }},
             {std::string("deposit"),
              ccxt::dict{
                  {std::string("min"), std::any{}},
                  {std::string("max"), std::any{}},
              }},
         }},
        {std::string("networks"), networks},
        {std::string("info"), networksRaw},
    });
  }

  /**
   * @method
   * @name lbank#fetchMarkets
   * @description retrieves data on all markets for lbank
   * @see https://www.lbank.com/en-US/docs/index.html#trading-pairs
   * @see
   * https://www.lbank.com/en-US/docs/contract.html#query-contract-information-list
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<std::any>
  fetchMarkets(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any marketsPromises =
                            ccxt::list{this->fetchSpotMarkets(params),
                                       this->fetchSwapMarkets(params)};
                        std::any resolvedMarkets =
                            awaitValue(promiseAll(marketsPromises));
                        return this->arrayConcat(
                            ::getValue(resolvedMarkets, 0),
                            ::getValue(resolvedMarkets, 1));
                      })
        .share();
  }

  virtual std::shared_future<std::any>
  fetchSpotMarkets(std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any response =
                     awaitValue(this->spotPublicGetAccuracy(params));
                 //
                 //     {
                 //         "result": "true",
                 //         "data": [
                 //             {
                 //                 "symbol": "btc_usdt",
                 //                 "quantityAccuracy": "4",
                 //                 "minTranQua": "0.0001",
                 //                 "priceAccuracy": "2"
                 //             },
                 //         ],
                 //         "error_code": 0,
                 //         "ts": 1691560288484
                 //     }
                 //
                 std::any data = this->safeValue(response, std::string("data"),
                                                 ccxt::list{});
                 std::any result = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(data));
                      postFixIncrement(i)) {
                   std::any market = ::getValue(data, i);
                   std::any marketId =
                       this->safeString(market, std::string("symbol"));
                   std::any parts = split(marketId, std::string("_"));
                   std::any baseId = ::getValue(parts, 0);
                   std::any quoteId = ::getValue(parts, 1);
                   std::any base = this->safeCurrencyCode(baseId);
                   std::any quote = this->safeCurrencyCode(quoteId);
                   std::any symbol = add(add(base, std::string("/")), quote);
                   arrayPush(
                       result,
                       ccxt::dict{
                           {std::string("id"), marketId},
                           {std::string("symbol"), symbol},
                           {std::string("base"), base},
                           {std::string("quote"), quote},
                           {std::string("baseId"), baseId},
                           {std::string("quoteId"), quoteId},
                           {std::string("settle"), std::any{}},
                           {std::string("settleId"), std::any{}},
                           {std::string("type"), std::string("spot")},
                           {std::string("spot"), true},
                           {std::string("margin"), false},
                           {std::string("swap"), false},
                           {std::string("future"), false},
                           {std::string("option"), false},
                           {std::string("active"), true},
                           {std::string("contract"), false},
                           {std::string("linear"), std::any{}},
                           {std::string("inverse"), std::any{}},
                           {std::string("contractSize"), std::any{}},
                           {std::string("expiry"), std::any{}},
                           {std::string("expiryDatetime"), std::any{}},
                           {std::string("strike"), std::any{}},
                           {std::string("optionType"), std::any{}},
                           {std::string("precision"),
                            ccxt::dict{
                                {std::string("amount"),
                                 this->parseNumber(
                                     this->parsePrecision(this->safeString(
                                         market,
                                         std::string("quantityAccuracy"))))},
                                {std::string("price"),
                                 this->parseNumber(
                                     this->parsePrecision(this->safeString(
                                         market,
                                         std::string("priceAccuracy"))))},
                            }},
                           {std::string("limits"),
                            ccxt::dict{
                                {std::string("leverage"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("amount"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market, std::string("minTranQua"))},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("price"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("cost"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"), std::any{}},
                                 }},
                            }},
                           {std::string("created"), std::any{}},
                           {std::string("info"), market},
                       });
                 }
                 return result;
               })
        .share();
  }

  virtual std::shared_future<std::any>
  fetchSwapMarkets(std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any request = ccxt::dict{
                     {std::string("productGroup"), std::string("SwapU")},
                 };
                 std::any response = awaitValue(
                     this->contractPublicGetCfdOpenApiV1PubInstrument(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "data": [
                 //             {
                 //                 "priceLimitUpperValue": 0.2,
                 //                 "symbol": "BTCUSDT",
                 //                 "volumeTick": 0.0001,
                 //                 "indexPrice": "29707.70200000",
                 //                 "minOrderVolume": "0.0001",
                 //                 "priceTick": 0.1,
                 //                 "maxOrderVolume": "30.0",
                 //                 "baseCurrency": "BTC",
                 //                 "volumeMultiple": 1.0,
                 //                 "exchangeID": "Exchange",
                 //                 "priceCurrency": "USDT",
                 //                 "priceLimitLowerValue": 0.2,
                 //                 "clearCurrency": "USDT",
                 //                 "symbolName": "BTCUSDT",
                 //                 "defaultLeverage": 20.0,
                 //                 "minOrderCost": "5.0"
                 //             },
                 //         ],
                 //         "error_code": 0,
                 //         "msg": "Success",
                 //         "result": "true",
                 //         "success": true
                 //     }
                 //
                 std::any data = this->safeValue(response, std::string("data"),
                                                 ccxt::list{});
                 std::any result = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(data));
                      postFixIncrement(i)) {
                   std::any market = ::getValue(data, i);
                   std::any marketId =
                       this->safeString(market, std::string("symbol"));
                   std::any baseId =
                       this->safeString(market, std::string("baseCurrency"));
                   std::any settleId =
                       this->safeString(market, std::string("clearCurrency"));
                   std::any quoteId = settleId;
                   std::any base = this->safeCurrencyCode(baseId);
                   std::any quote = this->safeCurrencyCode(quoteId);
                   std::any settle = this->safeCurrencyCode(settleId);
                   std::any symbol =
                       add(add(add(add(base, std::string("/")), quote),
                               std::string(":")),
                           settle);
                   arrayPush(
                       result,
                       ccxt::dict{
                           {std::string("id"), marketId},
                           {std::string("symbol"), symbol},
                           {std::string("base"), base},
                           {std::string("quote"), quote},
                           {std::string("settle"), settle},
                           {std::string("baseId"), baseId},
                           {std::string("quoteId"), quoteId},
                           {std::string("settleId"), settleId},
                           {std::string("type"), std::string("swap")},
                           {std::string("spot"), false},
                           {std::string("margin"), false},
                           {std::string("swap"), true},
                           {std::string("future"), false},
                           {std::string("option"), false},
                           {std::string("active"), true},
                           {std::string("contract"), true},
                           {std::string("linear"), true},
                           {std::string("inverse"), false},
                           {std::string("contractSize"),
                            this->safeNumber(market,
                                             std::string("volumeMultiple"))},
                           {std::string("expiry"), std::any{}},
                           {std::string("expiryDatetime"), std::any{}},
                           {std::string("strike"), std::any{}},
                           {std::string("optionType"), std::any{}},
                           {std::string("precision"),
                            ccxt::dict{
                                {std::string("amount"),
                                 this->safeNumber(market,
                                                  std::string("volumeTick"))},
                                {std::string("price"),
                                 this->safeNumber(market,
                                                  std::string("priceTick"))},
                            }},
                           {std::string("limits"),
                            ccxt::dict{
                                {std::string("leverage"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("amount"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market,
                                          std::string("minOrderVolume"))},
                                     {std::string("max"),
                                      this->safeNumber(
                                          market,
                                          std::string("maxOrderVolume"))},
                                 }},
                                {std::string("price"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("cost"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market, std::string("minOrderCost"))},
                                     {std::string("max"), std::any{}},
                                 }},
                            }},
                           {std::string("created"), std::any{}},
                           {std::string("info"), market},
                       });
                 }
                 return result;
               })
        .share();
  }

  std::any parseTicker(std::any ticker, std::any market = std::any{}) override {
    //
    // spot: fetchTicker, fetchTickers
    //
    //     {
    //         "symbol": "btc_usdt",
    //         "ticker": {
    //             "high": "29695.57",
    //             "vol": "6890.2789",
    //             "low": "29110",
    //             "change": "0.58",
    //             "turnover": "202769821.06",
    //             "latest": "29405.98"
    //         },
    //         "timestamp": :1692064274908
    //     }
    //
    // swap: fetchTickers
    //
    //     {
    //         "lastTime": 1784884932,
    //         "prePositionFeeRate": "0.000053",
    //         "volume": "2435.459",
    //         "symbol": "BTCUSDT",
    //         "highestPrice": "29446.5",
    //         "lowestPrice": "29362.9",
    //         "openPrice": "29419.5",
    //         "markedPrice": "29385.1",
    //         "turnover": "36345526.2438402",
    //         "lastPrice": "29387.0"
    //     }
    //
    std::any timestamp = this->safeInteger(ticker, std::string("timestamp"));
    if (isTrue(isEqual(timestamp, std::any{}))) {
      timestamp = this->safeTimestamp(ticker, std::string("lastTime"));
    }
    std::any marketId = this->safeString(ticker, std::string("symbol"));
    std::any symbol = this->safeSymbol(marketId, market);
    std::any tickerData =
        this->safeValue(ticker, std::string("ticker"), ccxt::dict{});
    market = this->safeMarket(marketId, market);
    std::any data =
        (isTrue((isEqual(::getValue(market, std::string("contract")), true)))
             ? std::any(ticker)
             : std::any(tickerData));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"),
             this->safeString2(data, std::string("high"),
                               std::string("highestPrice"))},
            {std::string("low"), this->safeString2(data, std::string("low"),
                                                   std::string("lowestPrice"))},
            {std::string("bid"), std::any{}},
            {std::string("bidVolume"), std::any{}},
            {std::string("ask"), std::any{}},
            {std::string("askVolume"), std::any{}},
            {std::string("vwap"), std::any{}},
            {std::string("open"),
             this->safeString(data, std::string("openPrice"))},
            {std::string("close"), std::any{}},
            {std::string("last"), this->safeString2(data, std::string("latest"),
                                                    std::string("lastPrice"))},
            {std::string("previousClose"), std::any{}},
            {std::string("change"), std::any{}},
            {std::string("percentage"),
             this->safeString(data, std::string("change"))},
            {std::string("average"), std::any{}},
            {std::string("baseVolume"),
             this->safeString2(data, std::string("vol"),
                               std::string("volume"))},
            {std::string("quoteVolume"),
             this->safeString(data, std::string("turnover"))},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name lbank#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see
   * https://www.lbank.com/en-US/docs/index.html#query-current-market-data-new
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchTicker(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   std::any responseForSwap = awaitValue(this->fetchTickers(
                       ccxt::list{::getValue(market, std::string("symbol"))},
                       params));
                   return this->safeValue(
                       responseForSwap,
                       ::getValue(market, std::string("symbol")));
                 }
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response = awaitValue(this->spotPublicGetTicker24hr(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "result": "true",
                 //         "data": [
                 //             {
                 //                 "symbol": "btc_usdt",
                 //                 "ticker": {
                 //                     "high": "29695.57",
                 //                     "vol": "6890.2789",
                 //                     "low": "29110",
                 //                     "change": "0.58",
                 //                     "turnover": "202769821.06",
                 //                     "latest": "29405.98"
                 //                 },
                 //                 "timestamp": :1692064274908
                 //             }
                 //         ],
                 //         "error_code": 0,
                 //         "ts": :1692064276872
                 //     }
                 //
                 std::any data = this->safeValue(response, std::string("data"),
                                                 ccxt::list{});
                 std::any first = this->safeDict(data, 0, ccxt::dict{});
                 return this->parseTicker(first, market);
               })
        .share();
  }

  /**
   * @method
   * @name lbank#fetchTickers
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @see
   * https://www.lbank.com/en-US/docs/index.html#query-current-market-data-new
   * @see
   * https://www.lbank.com/en-US/docs/contract.html#query-contract-market-list
   * @param {string[]|undefined} symbols unified symbols of the markets to fetch
   * the ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchTickers(std::any symbols = std::any{},
               std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = std::any{};
                        if (isTrue(!isEqual(symbols, std::any{}))) {
                          symbols = this->marketSymbols(symbols);
                          std::any symbolsLength = getArrayLength(symbols);
                          if (isTrue(isGreaterThan(symbolsLength, 0))) {
                            market = this->market(::getValue(symbols, 0));
                          }
                        }
                        std::any request = ccxt::dict{};
                        std::any type = std::any{};
                        std::any typeparamsVariable =
                            this->handleMarketTypeAndParams(
                                std::string("fetchTickers"), market, params);
                        type = ::getValue(typeparamsVariable, 0);
                        params = ::getValue(typeparamsVariable, 1);
                        std::any response = std::any{};
                        if (isTrue(isEqual(type, std::string("swap")))) {
                          ::setValue(request, std::string("productGroup"),
                                     std::string("SwapU"));
                          response = awaitValue(
                              this->contractPublicGetCfdOpenApiV1PubMarketData(
                                  this->extend(request, params)));
                        } else {
                          ::setValue(request, std::string("symbol"),
                                     std::string("all"));
                          response = awaitValue(this->spotPublicGetTicker24hr(
                              this->extend(request, params)));
                        }
                        //
                        // spot
                        //
                        //     {
                        //         "result": "true",
                        //         "data": [
                        //             {
                        //                 "symbol": "btc_usdt",
                        //                 "ticker": {
                        //                     "high": "29695.57",
                        //                     "vol": "6890.2789",
                        //                     "low": "29110",
                        //                     "change": "0.58",
                        //                     "turnover": "202769821.06",
                        //                     "latest": "29405.98"
                        //                 },
                        //                 "timestamp": :1692064274908
                        //             }
                        //         ],
                        //         "error_code": 0,
                        //         "ts": :1692064276872
                        //     }
                        //
                        // swap
                        //
                        //     {
                        //         "data": [
                        //             {
                        //                 "prePositionFeeRate": "0.000053",
                        //                 "volume": "2435.459",
                        //                 "symbol": "BTCUSDT",
                        //                 "highestPrice": "29446.5",
                        //                 "lowestPrice": "29362.9",
                        //                 "openPrice": "29419.5",
                        //                 "markedPrice": "29385.1",
                        //                 "turnover": "36345526.2438402",
                        //                 "lastPrice": "29387.0"
                        //             },
                        //         ],
                        //         "error_code": 0,
                        //         "msg": "Success",
                        //         "result": "true",
                        //         "success": true
                        //     }
                        //
                        std::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseTickers(data, symbols);
                      })
        .share();
  }

  /**
   * @method
   * @name lbank#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see https://www.lbank.com/en-US/docs/index.html#query-market-depth
   * @see https://www.lbank.com/en-US/docs/contract.html#get-handicap
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<std::any>
  fetchOrderBook(std::any symbol, std::any limit = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(isEqual(limit, std::any{}))) {
                   limit = 60;
                 }
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any type = std::any{};
                 std::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("fetchOrderBook"), market, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(isEqual(type, std::string("swap")))) {
                   ::setValue(request, std::string("depth"), limit);
                   response = awaitValue(
                       this->contractPublicGetCfdOpenApiV1PubMarketOrder(
                           this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("size"), limit);
                   response = awaitValue(
                       this->spotPublicGetDepth(this->extend(request, params)));
                 }
                 //
                 // spot
                 //
                 //     {
                 //         "result": "true",
                 //         "data": {
                 //             "asks": [
                 //                 ["29243.37", "2.8783"],
                 //                 ["29243.39", "2.2842"],
                 //                 ["29243.4", "0.0337"]
                 //             ],
                 //             "bids": [
                 //                 ["29243.36", "1.5258"],
                 //                 ["29243.34", "0.8218"],
                 //                 ["29243.28", "1.285"]
                 //             ],
                 //             "timestamp": :1692157328820
                 //         },
                 //         "error_code": 0,
                 //         "ts": :1692157328820
                 //     }
                 //
                 // swap
                 //
                 //     {
                 //         "data": {
                 //             "symbol": "BTCUSDT",
                 //             "asks": [
                 //                 {
                 //                     "volume": "14.6535",
                 //                     "price": "29234.2",
                 //                     "orders": "1"
                 //                 },
                 //             ],
                 //             "bids": [
                 //                 {
                 //                     "volume": "13.4899",
                 //                     "price": "29234.1",
                 //                     "orders": "4"
                 //                 },
                 //             ]
                 //         },
                 //         "error_code": 0,
                 //         "msg": "Success",
                 //         "result": "true",
                 //         "success": true
                 //     }
                 //
                 std::any orderbook = this->safeValue(
                     response, std::string("data"), ccxt::dict{});
                 std::any timestamp = this->milliseconds();
                 if (isTrue(isEqual(::getValue(market, std::string("swap")),
                                    true))) {
                   return this->parseOrderBook(
                       orderbook, ::getValue(market, std::string("symbol")),
                       timestamp, std::string("bids"), std::string("asks"),
                       std::string("price"), std::string("volume"));
                 }
                 return this->parseOrderBook(
                     orderbook, ::getValue(market, std::string("symbol")),
                     timestamp, std::string("bids"), std::string("asks"));
               })
        .share();
  }

  std::any parseTrade(std::any trade, std::any market = std::any{}) override {
    //
    // fetchTrades (old) spotPublicGetTrades
    //
    //      {
    //          "date_ms":1647021989789,
    //          "amount":0.0028,
    //          "price":38804.2,
    //          "type":"buy",
    //          "tid":"52d5616ee35c43019edddebe59b3e094"
    //      }
    //
    //
    // fetchTrades (new) spotPublicGetTradesSupplement
    //
    //      {
    //          "quoteQty":1675.048485,
    //          "price":0.127545,
    //          "qty":13133,
    //          "id":"3589541dc22e4357b227283650f714e2",
    //          "time":1648058297110,
    //          "isBuyerMaker":false
    //      }
    //
    // fetchMyTrades (private)
    //
    //      {
    //          "orderUuid":"38b4e7a4-14f6-45fd-aba1-1a37024124a0",
    //          "tradeFeeRate":0.0010000000,
    //          "dealTime":1648500944496,
    //          "dealQuantity":30.00000000000000000000,
    //          "tradeFee":0.00453300000000000000,
    //          "txUuid":"11f3850cc6214ea3b495adad3a032794",
    //          "dealPrice":0.15111300000000000000,
    //          "dealVolumePrice":4.53339000000000000000,
    //          "tradeType":"sell_market"
    //      }
    //
    std::any timestamp =
        this->safeInteger2(trade, std::string("date_ms"), std::string("time"));
    if (isTrue(isEqual(timestamp, std::any{}))) {
      timestamp = this->safeInteger(trade, std::string("dealTime"));
    }
    std::any amountString =
        this->safeString2(trade, std::string("amount"), std::string("qty"));
    if (isTrue(isEqual(amountString, std::any{}))) {
      amountString = this->safeString(trade, std::string("dealQuantity"));
    }
    std::any priceString = this->safeString(trade, std::string("price"));
    if (isTrue(isEqual(priceString, std::any{}))) {
      priceString = this->safeString(trade, std::string("dealPrice"));
    }
    std::any costString = this->safeString(trade, std::string("quoteQty"));
    if (isTrue(isEqual(costString, std::any{}))) {
      costString = this->safeString(trade, std::string("dealVolumePrice"));
    }
    std::any side =
        this->safeString2(trade, std::string("tradeType"), std::string("type"));
    std::any type = std::any{};
    std::any takerOrMaker = std::any{};
    if (isTrue(!isEqual(side, std::any{}))) {
      std::any parts = split(side, std::string("_"));
      side = this->safeString(parts, 0);
      std::any typePart = this->safeString(parts, 1);
      type = std::string("limit");
      takerOrMaker = std::string("taker");
      if (isTrue(!isEqual(typePart, std::any{}))) {
        if (isTrue(isEqual(typePart, std::string("market")))) {
          type = std::string("market");
        } else if (isTrue(isEqual(typePart, std::string("maker")))) {
          takerOrMaker = std::string("maker");
        }
      }
    }
    std::any id =
        this->safeString2(trade, std::string("tid"), std::string("id"));
    if (isTrue(isEqual(id, std::any{}))) {
      id = this->safeString(trade, std::string("txUuid"));
    }
    std::any order = this->safeString(trade, std::string("orderUuid"));
    std::any symbol = this->safeSymbol(std::any{}, market);
    std::any fee = std::any{};
    std::any feeCost = this->safeString(trade, std::string("tradeFee"));
    if (isTrue(!isEqual(feeCost, std::any{}))) {
      std::any feeCurr =
          (isTrue((isEqual(side, std::string("buy"))))
               ? std::any(this->safeString(market, std::string("base")))
               : std::any(this->safeString(market, std::string("quote"))));
      fee = ccxt::dict{
          {std::string("cost"), feeCost},
          {std::string("currency"), feeCurr},
          {std::string("rate"),
           this->safeString(trade, std::string("tradeFeeRate"))},
      };
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), symbol},
            {std::string("id"), id},
            {std::string("order"), order},
            {std::string("type"), type},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("side"), side},
            {std::string("price"), priceString},
            {std::string("amount"), amountString},
            {std::string("cost"), costString},
            {std::string("fee"), fee},
            {std::string("info"), trade},
        },
        market);
  }

  /**
   * @method
   * @name lbank#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see
   * https://www.lbank.com/en-US/docs/index.html#query-historical-transactions
   * @see https://www.lbank.com/en-US/docs/index.html#recent-transactions-list
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<std::any>
  fetchTrades(std::any symbol, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("time"), since);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("size"),
                              mathMin(limit, 600));
                 } else {
                   ::setValue(request, std::string("size"), 600); // max
                 }
                 std::any options = this->safeValue(
                     this->options, std::string("fetchTrades"), ccxt::dict{});
                 std::any defaultMethod =
                     this->safeString(options, std::string("method"),
                                      std::string("spotPublicGetTrades"));
                 std::any method = this->safeString(
                     params, std::string("method"), defaultMethod);
                 params = this->omit(params, std::string("method"));
                 std::any response = std::any{};
                 if (isTrue(isEqual(
                         method,
                         std::string("spotPublicGetSupplementTrades")))) {
                   response = awaitValue(this->spotPublicGetSupplementTrades(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->spotPublicGetTrades(
                       this->extend(request, params)));
                 }
                 //
                 //      {
                 //          "result":"true",
                 //          "data": [
                 //              {
                 //                  "date_ms":1647021989789,
                 //                  "amount":0.0028,
                 //                  "price":38804.2,
                 //                  "type":"buy",
                 //                  "tid":"52d5616ee35c43019edddebe59b3e094"
                 //               }
                 //           ],
                 //           "error_code":0,
                 //           "ts":1647021999308
                 //      }
                 //
                 std::any trades = this->safeList(response, std::string("data"),
                                                  ccxt::list{});
                 return this->parseTrades(trades, market, since, limit);
               })
        .share();
  }

  std::any parseOHLCV(std::any ohlcv, std::any market = std::any{}) override {
    //
    //   [
    //     1482311500, // timestamp
    //     5423.23,    // open
    //     5472.80,    // high
    //     5516.09,    // low
    //     5462,       // close
    //     234.3250    // volume
    //   ],
    //
    return ccxt::list{
        this->safeTimestamp(ohlcv, 0), this->safeNumber(ohlcv, 1),
        this->safeNumber(ohlcv, 2),    this->safeNumber(ohlcv, 3),
        this->safeNumber(ohlcv, 4),    this->safeNumber(ohlcv, 5)};
  }

  /**
   * @method
   * @name lbank#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://www.lbank.com/en-US/docs/index.html#query-k-bar-data
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<std::any>
  fetchOHLCV(std::any symbol, std::any timeframe = std::string("1m"),
             std::any since = std::any{}, std::any limit = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 // endpoint doesnt work
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(isEqual(limit, std::any{}))) {
                   limit = 100;
                 } else {
                   limit = mathMin(limit, 2000);
                 }
                 if (isTrue(isEqual(since, std::any{}))) {
                   std::any duration = this->parseTimeframe(timeframe);
                   since =
                       subtract(this->milliseconds(),
                                (multiply(multiply(duration, 1000), limit)));
                 }
                 std::any parsedSince = this->parseToInt(divide(since, 1000));
                 std::any parsedLimit =
                     mathMin(add(limit, 1), 2000); // max 2000;
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("type"),
                      this->safeString(this->timeframes, timeframe, timeframe)},
                     {std::string("time"), parsedSince},
                     {std::string("size"), parsedLimit},
                 };
                 std::any response = awaitValue(
                     this->spotPublicGetKline(this->extend(request, params)));
                 std::any ohlcvs = this->safeList(response, std::string("data"),
                                                  ccxt::list{});
                 //
                 //
                 // [
                 //   [
                 //     1482311500,
                 //     5423.23,
                 //     5472.80,
                 //     5516.09,
                 //     5462,
                 //     234.3250
                 //   ],
                 //   [
                 //     1482311400,
                 //     5432.52,
                 //     5459.87,
                 //     5414.30,
                 //     5428.23,
                 //     213.7329
                 //   ]
                 // ]
                 //
                 return this->parseOHLCVs(ohlcvs, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  std::any parseBalance(std::any response) override {
    //
    // spotPrivatePostUserInfo
    //
    //      {
    //          "toBtc": {
    //              "egc:": "0",
    //              "iog": "0",
    //              "ksm": "0",
    //              },
    //          "freeze": {
    //              "egc": "0",
    //              "iog": "0",
    //              "ksm": "0" ,
    //              },
    //          "asset": {
    //              "egc": "0",
    //              "iog": "0",
    //              "ksm": "0",
    //              },
    //          "free": {
    //              "egc": "0",
    //              "iog": "0",
    //              "ksm": "0",
    //              }
    //      }
    //
    // spotPrivatePostSupplementUserInfoAccount
    //
    //      {
    //          "balances":[
    //              {
    //                  "asset":"lbk",
    //                  "free":"0",
    //                  "locked":"0"
    //              }, ...
    //          ]
    //      }
    //
    // spotPrivatePostSupplementUserInfo
    //
    //      [
    //          {
    //              "usableAmt":"31.45130723",
    //              "assetAmt":"31.45130723",
    //              "networkList":[
    //                  {
    //                      "isDefault":true,
    //                      "withdrawFeeRate":"",
    //                      "name":"bep20(bsc)",
    //                      "withdrawMin":30,
    //                      "minLimit":0.0001,
    //                      "minDeposit":0.0001,
    //                      "feeAssetCode":"doge",
    //                      "withdrawFee":"30",
    //                      "type":1,
    //                      "coin":"doge",
    //                      "network":"bsc"
    //                  },
    //                  {
    //                      "isDefault":false,
    //                      "withdrawFeeRate":"",
    //                      "name":"dogecoin",
    //                      "withdrawMin":10,
    //                      "minLimit":0.0001,
    //                      "minDeposit":10,
    //                      "feeAssetCode":"doge",
    //                      "withdrawFee":"10",
    //                      "type":1,
    //                      "coin":"doge",
    //                      "network":"dogecoin"
    //                  }
    //              ],
    //              "freezeAmt":"0",
    //              "coin":"doge"
    //          }, ...
    //      ]
    //
    std::any timestamp = this->safeInteger(response, std::string("ts"));
    std::any result = ccxt::dict{
        {std::string("info"), response},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
    };
    std::any data = this->safeValue(response, std::string("data"));
    // from spotPrivatePostUserInfo
    std::any toBtc = this->safeValue(data, std::string("toBtc"));
    if (isTrue(!isEqual(toBtc, std::any{}))) {
      std::any used =
          this->safeValue(data, std::string("freeze"), ccxt::dict{});
      std::any free = this->safeValue(data, std::string("free"), ccxt::dict{});
      std::any currencies = getObjectKeys(free);
      for (std::any i = 0; isLessThan(i, getArrayLength(currencies));
           postFixIncrement(i)) {
        std::any currencyId = ::getValue(currencies, i);
        std::any code = this->safeCurrencyCode(currencyId);
        std::any account = this->account();
        ::setValue(account, std::string("used"),
                   this->safeString(used, currencyId));
        ::setValue(account, std::string("free"),
                   this->safeString(free, currencyId));
        if (isTrue(!isEqual(code, std::any{}))) {
          ::setValue(result, code, account);
        }
      }
      return this->safeBalance(result);
    }
    // from spotPrivatePostSupplementUserInfoAccount
    std::any balances = this->safeValue(data, std::string("balances"));
    if (isTrue(!isEqual(balances, std::any{}))) {
      for (std::any i = 0; isLessThan(i, getArrayLength(balances));
           postFixIncrement(i)) {
        std::any item = ::getValue(balances, i);
        std::any currencyId = this->safeString(item, std::string("asset"));
        std::any codeInner = this->safeCurrencyCode(currencyId);
        std::any account = this->account();
        ::setValue(account, std::string("free"),
                   this->safeString(item, std::string("free")));
        ::setValue(account, std::string("used"),
                   this->safeString(item, std::string("locked")));
        if (isTrue(!isEqual(codeInner, std::any{}))) {
          ::setValue(result, codeInner, account);
        }
      }
      return this->safeBalance(result);
    }
    // from spotPrivatePostSupplementUserInfo
    std::any isArray = ::isArray(data);
    if (isTrue(isEqual(isArray, true))) {
      for (std::any i = 0; isLessThan(i, getArrayLength(data));
           postFixIncrement(i)) {
        std::any item = ::getValue(data, i);
        std::any currencyId = this->safeString(item, std::string("coin"));
        std::any codeInner = this->safeCurrencyCode(currencyId);
        std::any account = this->account();
        ::setValue(account, std::string("free"),
                   this->safeString(item, std::string("usableAmt")));
        ::setValue(account, std::string("used"),
                   this->safeString(item, std::string("freezeAmt")));
        if (isTrue(!isEqual(codeInner, std::any{}))) {
          ::setValue(result, codeInner, account);
        }
      }
      return this->safeBalance(result);
    }
    return this->safeBalance(result);
  }

  std::any parseFundingRate(std::any ticker,
                            std::any market = std::any{}) override {
    // {
    //     "symbol": "BTCUSDT",
    //     "highestPrice": "69495.5",
    //     "underlyingPrice": "68455.904",
    //     "lowestPrice": "68182.1",
    //     "openPrice": "68762.4",
    //     "positionFeeRate": "0.0001",
    //     "volume": "33534.2858",
    //     "markedPrice": "68434.1",
    //     "turnover": "1200636218.210558",
    //     "positionFeeTime": "28800",
    //     "lastPrice": "68427.3",
    //     "nextFeeTime": "1730736000000",
    //     "fundingRate": "0.0001",
    // }
    std::any marketId = this->safeString(ticker, std::string("symbol"));
    std::any symbol = this->safeSymbol(marketId, market);
    std::any markPrice = this->safeNumber(ticker, std::string("markedPrice"));
    std::any indexPrice =
        this->safeNumber(ticker, std::string("underlyingPrice"));
    std::any fundingRate = this->safeNumber(ticker, std::string("fundingRate"));
    std::any fundingTime =
        this->safeInteger(ticker, std::string("nextFeeTime"));
    std::any positionFeeTime =
        this->safeInteger(ticker, std::string("positionFeeTime"));
    std::any intervalString = std::any{};
    if (isTrue(!isEqual(positionFeeTime, std::any{}))) {
      std::any interval =
          this->parseToInt(divide(divide(positionFeeTime, 60), 60));
      intervalString = add(toString(interval), std::string("h"));
    }
    return ccxt::dict{
        {std::string("info"), ticker},
        {std::string("symbol"), symbol},
        {std::string("markPrice"), markPrice},
        {std::string("indexPrice"), indexPrice},
        {std::string("fundingRate"), fundingRate},
        {std::string("fundingTimestamp"), fundingTime},
        {std::string("fundingDatetime"), this->iso8601(fundingTime)},
        {std::string("timestamp"), std::any{}},
        {std::string("datetime"), std::any{}},
        {std::string("nextFundingRate"), std::any{}},
        {std::string("nextFundingTimestamp"), std::any{}},
        {std::string("nextFundingDatetime"), std::any{}},
        {std::string("previousFundingRate"), std::any{}},
        {std::string("previousFundingTimestamp"), std::any{}},
        {std::string("previousFundingDatetime"), std::any{}},
        {std::string("interval"), intervalString},
    };
  }

  /**
   * @method
   * @name lbank#fetchFundingRate
   * @description fetch the current funding rate
   * @see
   * https://www.lbank.com/en-US/docs/contract.html#query-contract-market-list
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [funding rate structure]{@link
   * https://docs.ccxt.com/?id=funding-rate-structure}
   */
  std::shared_future<std::any>
  fetchFundingRate(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any responseForSwap = awaitValue(this->fetchFundingRates(
                     ccxt::list{::getValue(market, std::string("symbol"))},
                     params));
                 return this->safeValue(
                     responseForSwap,
                     ::getValue(market, std::string("symbol")));
               })
        .share();
  }

  /**
   * @method
   * @name lbank#fetchFundingRates
   * @description fetch the funding rate for multiple markets
   * @see
   * https://www.lbank.com/en-US/docs/contract.html#query-contract-market-list
   * @param {string[]|undefined} symbols list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rates-structure}, indexed by market
   * symbols
   */
  std::shared_future<std::any>
  fetchFundingRates(std::any symbols = std::any{},
                    std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        symbols = this->marketSymbols(symbols);
                        std::any request = ccxt::dict{
                            {std::string("productGroup"), std::string("SwapU")},
                        };
                        std::any response = awaitValue(
                            this->contractPublicGetCfdOpenApiV1PubMarketData(
                                this->extend(request, params)));
                        // {
                        //     "data": [
                        //         {
                        //             "symbol": "BTCUSDT",
                        //             "highestPrice": "69495.5",
                        //             "underlyingPrice": "68455.904",
                        //             "lowestPrice": "68182.1",
                        //             "openPrice": "68762.4",
                        //             "positionFeeRate": "0.0001",
                        //             "volume": "33534.2858",
                        //             "markedPrice": "68434.1",
                        //             "turnover": "1200636218.210558",
                        //             "positionFeeTime": "28800",
                        //             "lastPrice": "68427.3",
                        //             "nextFeeTime": "1730736000000",
                        //             "fundingRate": "0.0001",
                        //         }
                        //     ],
                        //     "error_code": "0",
                        //     "msg": "Success",
                        //     "result": "true",
                        //     "success": True,
                        // }
                        std::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseFundingRates(data, symbols);
                      })
        .share();
  }

  /**
   * @method
   * @name lbank#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see https://www.lbank.com/en-US/docs/index.html#asset-information
   * @see https://www.lbank.com/en-US/docs/index.html#account-information
   * @see https://www.lbank.com/en-US/docs/index.html#get-all-coins-information
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<std::any>
  fetchBalance(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any options = this->safeValue(
                     this->options, std::string("fetchBalance"), ccxt::dict{});
                 std::any defaultMethod = this->safeString(
                     options, std::string("method"),
                     std::string("spotPrivatePostSupplementUserInfo"));
                 std::any method = this->safeString(
                     params, std::string("method"), defaultMethod);
                 std::any response = std::any{};
                 if (isTrue(isEqual(
                         method,
                         std::string(
                             "spotPrivatePostSupplementUserInfoAccount")))) {
                   response = awaitValue(
                       this->spotPrivatePostSupplementUserInfoAccount());
                 } else if (isTrue(isEqual(
                                method,
                                std::string("spotPrivatePostUserInfo")))) {
                   response = awaitValue(this->spotPrivatePostUserInfo());
                 } else {
                   response =
                       awaitValue(this->spotPrivatePostSupplementUserInfo());
                 }
                 //
                 //    {
                 //        "result": "true",
                 //        "data": [
                 //            {
                 //                "usableAmt": "14.36",
                 //                "assetAmt": "14.36",
                 //                "networkList": [
                 //                    {
                 //                        "isDefault": false,
                 //                        "withdrawFeeRate": "",
                 //                        "name": "erc20",
                 //                        "withdrawMin": 30,
                 //                        "minLimit": 0.0001,
                 //                        "minDeposit": 20,
                 //                        "feeAssetCode": "usdt",
                 //                        "withdrawFee": "30",
                 //                        "type": 1,
                 //                        "coin": "usdt",
                 //                        "network": "eth"
                 //                    },
                 //                    ...
                 //                ],
                 //                "freezeAmt": "0",
                 //                "coin": "ada"
                 //            }
                 //        ],
                 //        "code": 0
                 //    }
                 //
                 std::any balanceResponse =
                     (isTrue((isEqual(response, std::any{})))
                          ? std::any(ccxt::dict{})
                          : std::any(response));
                 std::any balanceResult = this->parseBalance(balanceResponse);
                 if (isTrue(isEqual(balanceResult, std::any{}))) {
                   throw NullResponse(toString(
                       add(this->id,
                           std::string(
                               " fetchBalance() returned empty response"))));
                 }
                 return balanceResult;
               })
        .share();
  }

  virtual std::any parseTradingFee(std::any fee, std::any market = std::any{}) {
    //
    //      {
    //          "symbol":"skt_usdt",
    //          "makerCommission":"0.10",
    //          "takerCommission":"0.10"
    //      }
    //
    std::any marketId = this->safeString(fee, std::string("symbol"));
    std::any symbol = this->safeSymbol(marketId);
    return ccxt::dict{
        {std::string("info"), fee},
        {std::string("symbol"), symbol},
        {std::string("maker"),
         this->safeNumber(fee, std::string("makerCommission"))},
        {std::string("taker"),
         this->safeNumber(fee, std::string("takerCommission"))},
        {std::string("percentage"), std::any{}},
        {std::string("tierBased"), std::any{}},
    };
  }

  /**
   * @method
   * @name lbank#fetchTradingFee
   * @description fetch the trading fees for a market
   * @see https://www.lbank.com/en-US/docs/index.html#transaction-fee-rate-query
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [fee structure]{@link
   * https://docs.ccxt.com/?id=fee-structure}
   */
  std::shared_future<std::any>
  fetchTradingFee(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any market = this->market(symbol);
                 std::any result =
                     awaitValue(this->fetchTradingFees(this->extend(
                         params, ccxt::dict{
                                     {std::string("category"),
                                      ::getValue(market, std::string("id"))},
                                 })));
                 return this->safeDict(result, symbol);
               })
        .share();
  }

  /**
   * @method
   * @name lbank#fetchTradingFees
   * @description fetch the trading fees for multiple markets
   * @see https://www.lbank.com/en-US/docs/index.html#transaction-fee-rate-query
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
   */
  std::shared_future<std::any>
  fetchTradingFees(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 std::any response =
                     awaitValue(this->spotPrivatePostSupplementCustomerTradeFee(
                         this->extend(request, params)));
                 std::any fees = this->safeValue(response, std::string("data"),
                                                 ccxt::list{});
                 std::any result = ccxt::dict{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(fees));
                      postFixIncrement(i)) {
                   std::any fee = this->parseTradingFee(::getValue(fees, i));
                   std::any symbol = ::getValue(fee, std::string("symbol"));
                   ::setValue(result, symbol, fee);
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name lbank#createMarketBuyOrderWithCost
   * @description create a market buy order by providing the symbol and cost
   * @see https://www.lbank.com/en-US/docs/index.html#place-order
   * @see https://www.lbank.com/en-US/docs/index.html#place-an-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {float} cost how much you want to trade in units of the quote
   * currency
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createMarketBuyOrderWithCost(std::any symbol, std::any cost,
                               std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(!isEqual(::getValue(market, std::string("spot")),
                                     true))) {
                   throw NotSupported(toString(add(
                       this->id, std::string(" createMarketBuyOrderWithCost() "
                                             "supports spot orders only"))));
                 }
                 ::setValue(params,
                            std::string("createMarketBuyOrderRequiresPrice"),
                            false);
                 return awaitValue(this->createOrder(
                     symbol, std::string("market"), std::string("buy"), cost,
                     std::any{}, params));
               })
        .share();
  }

  /**
   * @method
   * @name lbank#createOrder
   * @description create a trade order
   * @see https://www.lbank.com/en-US/docs/index.html#place-order
   * @see https://www.lbank.com/en-US/docs/index.html#place-an-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any market = this->market(symbol);
                std::any clientOrderId =
                    this->safeString2(params, std::string("custom_id"),
                                      std::string("clientOrderId"));
                std::any postOnly =
                    this->safeBool(params, std::string("postOnly"), false);
                std::any timeInForce =
                    this->safeStringUpper(params, std::string("timeInForce"));
                params =
                    this->omit(params, ccxt::list{std::string("custom_id"),
                                                  std::string("clientOrderId"),
                                                  std::string("timeInForce"),
                                                  std::string("postOnly")});
                std::any request = ccxt::dict{
                    {std::string("symbol"),
                     ::getValue(market, std::string("id"))},
                };
                std::any ioc = (isEqual(timeInForce, std::string("IOC")));
                std::any fok = (isEqual(timeInForce, std::string("FOK")));
                std::any maker =
                    (isTrue((isEqual(postOnly, true))) ||
                     isTrue((isEqual(timeInForce, std::string("PO")))));
                if (isTrue(isTrue((isEqual(type, std::string("market")))) &&
                           isTrue((isTrue(isTrue(ioc) || isTrue(fok)) ||
                                   isTrue(maker))))) {
                  throw InvalidOrder(toString(add(
                      this->id,
                      std::string(" createOrder () does not allow market FOK, "
                                  "IOC, or postOnly orders. Only limit IOC, "
                                  "FOK, and postOnly orders are allowed"))));
                }
                if (isTrue(isEqual(type, std::string("limit")))) {
                  ::setValue(request, std::string("type"), side);
                  ::setValue(request, std::string("price"),
                             this->priceToPrecision(symbol, price));
                  ::setValue(request, std::string("amount"),
                             this->amountToPrecision(symbol, amount));
                  if (isTrue(ioc)) {
                    ::setValue(
                        request, std::string("type"),
                        add(add(side, std::string("_")), std::string("ioc")));
                  } else if (isTrue(fok)) {
                    ::setValue(
                        request, std::string("type"),
                        add(add(side, std::string("_")), std::string("fok")));
                  } else if (isTrue(maker)) {
                    ::setValue(
                        request, std::string("type"),
                        add(add(side, std::string("_")), std::string("maker")));
                  }
                } else if (isTrue(isEqual(type, std::string("market")))) {
                  if (isTrue(isEqual(side, std::string("sell")))) {
                    ::setValue(request, std::string("type"),
                               add(add(side, std::string("_")),
                                   std::string("market")));
                    ::setValue(request, std::string("amount"),
                               this->amountToPrecision(symbol, amount));
                  } else if (isTrue(isEqual(side, std::string("buy")))) {
                    ::setValue(request, std::string("type"),
                               add(add(side, std::string("_")),
                                   std::string("market")));
                    std::any quoteAmount = std::any{};
                    std::any createMarketBuyOrderRequiresPrice = true;
                    std::any createMarketBuyOrderRequiresPriceparamsVariable =
                        this->handleOptionAndParams(
                            params, std::string("createOrder"),
                            std::string("createMarketBuyOrderRequiresPrice"),
                            true);
                    createMarketBuyOrderRequiresPrice = ::getValue(
                        createMarketBuyOrderRequiresPriceparamsVariable, 0);
                    params = ::getValue(
                        createMarketBuyOrderRequiresPriceparamsVariable, 1);
                    std::any cost =
                        this->safeNumber(params, std::string("cost"));
                    params = this->omit(params, std::string("cost"));
                    if (isTrue(!isEqual(cost, std::any{}))) {
                      quoteAmount = this->costToPrecision(symbol, cost);
                    } else if (isTrue(createMarketBuyOrderRequiresPrice)) {
                      if (isTrue(isEqual(price, std::any{}))) {
                        throw InvalidOrder(toString(add(
                            this->id,
                            std::string(
                                " createOrder() requires the price argument "
                                "for market buy orders to calculate the total "
                                "cost to spend (amount * price), alternatively "
                                "set the createMarketBuyOrderRequiresPrice "
                                "option or param to false and pass the cost to "
                                "spend in the amount argument"))));
                      } else {
                        std::any amountString = this->numberToString(amount);
                        std::any priceString = this->numberToString(price);
                        std::any costRequest =
                            ccxt::Precise::stringMul(amountString, priceString);
                        quoteAmount =
                            this->costToPrecision(symbol, costRequest);
                      }
                    } else {
                      quoteAmount = this->costToPrecision(symbol, amount);
                    }
                    // market buys require filling the price param instead of
                    // the amount param, for market buys the price is treated as
                    // the cost by lbank
                    ::setValue(request, std::string("price"), quoteAmount);
                  }
                }
                if (isTrue(!isEqual(clientOrderId, std::any{}))) {
                  ::setValue(request, std::string("custom_id"), clientOrderId);
                }
                std::any options = this->safeValue(
                    this->options, std::string("createOrder"), ccxt::dict{});
                std::any defaultMethod = this->safeString(
                    options, std::string("method"),
                    std::string("spotPrivatePostSupplementCreateOrder"));
                std::any method = this->safeString(
                    params, std::string("method"), defaultMethod);
                params = this->omit(params, std::string("method"));
                std::any response = std::any{};
                if (isTrue(isEqual(
                        method, std::string("spotPrivatePostCreateOrder")))) {
                  response = awaitValue(this->spotPrivatePostCreateOrder(
                      this->extend(request, params)));
                } else {
                  response =
                      awaitValue(this->spotPrivatePostSupplementCreateOrder(
                          this->extend(request, params)));
                }
                //
                //      {
                //          "result":true,
                //          "data":{
                //              "symbol":"doge_usdt",
                //              "order_id":"0cf8a3de-4597-4296-af45-be7abaa06b07"
                //              },
                //          "error_code":0,
                //          "ts":1648162321043
                //      }
                //
                std::any result = this->safeValue(response, std::string("data"),
                                                  ccxt::dict{});
                return this->safeOrder(
                    ccxt::dict{
                        {std::string("id"),
                         this->safeString(result, std::string("order_id"))},
                        {std::string("info"), result},
                    },
                    market);
              })
            .share();
  }

  virtual std::any parseOrderStatus(std::any status) {
    std::any statuses = ccxt::dict{
        {std::string("-1"), std::string("canceled")},
        {std::string("0"), std::string("open")},
        {std::string("1"), std::string("open")},
        {std::string("2"), std::string("closed")},
        {std::string("3"), std::string("canceled")},
        {std::string("4"), std::string("closed")},
    };
    return this->safeString(statuses, status, status);
  }

  std::any parseOrder(std::any order, std::any market = std::any{}) override {
    //
    // fetchOrderSupplement (private)
    //
    //      {
    //          "cummulativeQuoteQty":0,
    //          "symbol":"doge_usdt",
    //          "executedQty":0,
    //          "orderId":"53d2d53e-70fb-4398-b722-f48571a5f61e",
    //          "origQty":1E+2,
    //          "price":0.05,
    //          "clientOrderId":null,
    //          "origQuoteOrderQty":5,
    //          "updateTime":1648163406000,
    //          "time":1648163139387,
    //          "type":"buy_maker",
    //          "status":-1
    //      }
    //
    //
    // fetchOrderDefault (private)
    //
    //      {
    //          "symbol":"shib_usdt",
    //          "amount":1,
    //          "create_time":1649367863356,
    //          "price":0.0000246103,
    //          "avg_price":0.00002466180000000104,
    //          "type":"buy_market",
    //          "order_id":"abe8b92d-86d9-4d6d-b71e-d14f5fb53ddf",
    //          "custom_id": "007",                                 // field
    //          only present if user creates it at order time
    //          "deal_amount":40548.54065802,
    //          "status":2
    //      }
    //
    // fetchOpenOrders (private)
    //
    //      {
    //          "cummulativeQuoteQty":0,
    //          "symbol":"doge_usdt",
    //          "executedQty":0,
    //          "orderId":"73878edf-008d-4e4c-8041-df1f1b2cd8bb",
    //          "origQty":100,
    //          "price":0.05,
    //          "origQuoteOrderQty":5,
    //          "updateTime":1648501762000,
    //          "time":1648501762353,
    //          "type":"buy",
    //          "status":0
    //      }
    //
    // fetchOrders (private)
    //
    //      {
    //          "cummulativeQuoteQty":0,
    //          "symbol":"doge_usdt",
    //          "executedQty":0,
    //          "orderId":"2cadc7cc-b5f6-486b-a5b4-d6ac49a9c186",
    //          "origQty":100,
    //          "price":0.05,
    //          "origQuoteOrderQty":5,
    //          "updateTime":1648501384000,
    //          "time":1648501363889,
    //          "type":"buy",
    //          "status":-1
    //      }
    //
    // cancelOrder
    //
    //    {
    //        "executedQty":0.0,
    //        "price":0.05,
    //        "origQty":100.0,
    //        "tradeType":"buy",
    //        "status":0
    //    }
    //
    // cancelAllOrders
    //
    //    {
    //        "executedQty":0.00000000000000000000,
    //        "orderId":"293ef71b-3e67-4962-af93-aa06990a045f",
    //        "price":0.05000000000000000000,
    //        "origQty":100.00000000000000000000,
    //        "tradeType":"buy",
    //        "status":0
    //    }
    //
    std::any id = this->safeString2(order, std::string("orderId"),
                                    std::string("order_id"));
    std::any clientOrderId = this->safeString2(
        order, std::string("clientOrderId"), std::string("custom_id"));
    std::any timestamp = this->safeInteger2(order, std::string("time"),
                                            std::string("create_time"));
    std::any rawStatus = this->safeString(order, std::string("status"));
    std::any marketId = this->safeString(order, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    std::any timeInForce = std::any{};
    std::any postOnly = false;
    std::any type = std::string("limit");
    std::any rawType = this->safeString2(
        order, std::string("type"),
        std::string("tradeType")); // buy, sell, buy_market, sell_market,
                                   // buy_maker,sell_maker,buy_ioc,sell_ioc,
                                   // buy_fok, sell_fok
    std::any parts = split(rawType, std::string("_"));
    std::any side = this->safeString(parts, 0);
    std::any typePart = this->safeString(
        parts, 1); // market, maker, ioc, fok or undefined (limit)
    if (isTrue(isEqual(typePart, std::string("market")))) {
      type = std::string("market");
    }
    if (isTrue(isEqual(typePart, std::string("maker")))) {
      postOnly = true;
      timeInForce = std::string("PO");
    }
    if (isTrue(isEqual(typePart, std::string("ioc")))) {
      timeInForce = std::string("IOC");
    }
    if (isTrue(isEqual(typePart, std::string("fok")))) {
      timeInForce = std::string("FOK");
    }
    std::any price = this->safeString(order, std::string("price"));
    std::any costString =
        this->safeString(order, std::string("cummulativeQuoteQty"));
    std::any amountString = std::any{};
    if (isTrue(!isEqual(rawType, std::string("buy_market")))) {
      amountString = this->safeString2(order, std::string("origQty"),
                                       std::string("amount"));
    }
    std::any filledString = this->safeString2(order, std::string("executedQty"),
                                              std::string("deal_amount"));
    return this->safeOrder(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("clientOrderId"), clientOrderId},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("timestamp"), timestamp},
            {std::string("lastTradeTimestamp"), std::any{}},
            {std::string("status"), this->parseOrderStatus(rawStatus)},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("type"), type},
            {std::string("timeInForce"), timeInForce},
            {std::string("postOnly"), postOnly},
            {std::string("side"), side},
            {std::string("price"), price},
            {std::string("triggerPrice"), std::any{}},
            {std::string("cost"), costString},
            {std::string("amount"), amountString},
            {std::string("filled"), filledString},
            {std::string("remaining"), std::any{}},
            {std::string("trades"), std::any{}},
            {std::string("fee"), std::any{}},
            {std::string("info"), order},
            {std::string("average"), std::any{}},
        },
        market);
  }

  /**
   * @method
   * @name lbank#fetchOrder
   * @description fetches information on an order made by the user
   * @see https://www.lbank.com/en-US/docs/index.html#query-order
   * @see https://www.lbank.com/en-US/docs/index.html#query-order-new
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOrder(std::any id, std::any symbol = std::any{},
             std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any method =
                     this->safeString(params, std::string("method"));
                 if (isTrue(isEqual(method, std::any{}))) {
                   std::any options = this->safeValue(
                       this->options, std::string("fetchOrder"), ccxt::dict{});
                   method =
                       this->safeString(options, std::string("method"),
                                        std::string("fetchOrderSupplement"));
                 }
                 if (isTrue(isEqual(method,
                                    std::string("fetchOrderSupplement")))) {
                   return awaitValue(
                       this->fetchOrderSupplement(id, symbol, params));
                 }
                 return awaitValue(this->fetchOrderDefault(id, symbol, params));
               })
        .share();
  }

  virtual std::shared_future<std::any>
  fetchOrderSupplement(std::any id, std::any symbol = std::any{},
                       std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " fetchOrder() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("orderId"), id},
                 };
                 std::any response =
                     awaitValue(this->spotPrivatePostSupplementOrdersInfo(
                         this->extend(request, params)));
                 //
                 //      {
                 //          "result":true,
                 //          "data":{
                 //              "cummulativeQuoteQty":0,
                 //              "symbol":"doge_usdt",
                 //              "executedQty":0,
                 //              "orderId":"53d2d53e-70fb-4398-b722-f48571a5f61e",
                 //              "origQty":1E+2,
                 //              "price":0.05,
                 //              "clientOrderId":null,
                 //              "origQuoteOrderQty":5,
                 //              "updateTime":1648163406000,
                 //              "time":1648163139387,
                 //              "type":"buy_maker",
                 //              "status":-1
                 //              },
                 //          "error_code":0,
                 //          "ts":1648164471827
                 //      }
                 //
                 std::any result = this->safeDict(response, std::string("data"),
                                                  ccxt::dict{});
                 return this->parseOrder(result);
               })
        .share();
  }

  virtual std::shared_future<std::any>
  fetchOrderDefault(std::any id, std::any symbol = std::any{},
                    std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 // Id can be a list of ids delimited by a comma
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " fetchOrder() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("order_id"), id},
                 };
                 std::any response = awaitValue(this->spotPrivatePostOrdersInfo(
                     this->extend(request, params)));
                 //
                 //      {
                 //          "result":true,
                 //          "data":[
                 //              {
                 //                  "symbol":"doge_usdt",
                 //                  "amount":18,
                 //                  "create_time":1647455223186,
                 //                  "price":0,
                 //                  "avg_price":0.113344,
                 //                  "type":"sell_market",
                 //                  "order_id":"d4ca1ddd-40d9-42c1-9717-5de435865bec",
                 //                  "deal_amount":18,
                 //                  "status":2
                 //                }
                 //            ],
                 //          "error_code":0,
                 //          "ts":1647455270776
                 //      }
                 //
                 std::any result = this->safeValue(
                     response, std::string("data"), ccxt::list{});
                 std::any numOrders = getArrayLength(result);
                 if (isTrue(isEqual(numOrders, 1))) {
                   return this->parseOrder(::getValue(result, 0));
                 } else {
                   throw BadRequest(toString(
                       add(this->id, std::string(" fetchOrder() can only fetch "
                                                 "one order at a time"))));
                 }
                 return std::any{};
               })
        .share();
  }

  /**
   * @method
   * @name lbank#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://www.lbank.com/en-US/docs/index.html#past-transaction-details
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trade structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchMyTrades() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 since =
                     this->safeValue(params, std::string("start_date"), since);
                 params = this->omit(params, std::string("start_date"));
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("size"), limit);
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(
                       request, std::string("start_date"),
                       this->ymd(since,
                                 std::string("-"))); // max query 2 days ago
                   ::setValue(request, std::string("end_date"),
                              this->ymd(add(since, 86400000),
                                        std::string("-"))); // will cover 2 days
                 }
                 std::any response =
                     awaitValue(this->spotPrivatePostTransactionHistory(
                         this->extend(request, params)));
                 //
                 //      {
                 //          "result":true,
                 //          "data":[
                 //              {
                 //                  "orderUuid":"38b4e7a4-14f6-45fd-aba1-1a37024124a0",
                 //                  "tradeFeeRate":0.0010000000,
                 //                  "dealTime":1648500944496,
                 //                  "dealQuantity":30.00000000000000000000,
                 //                  "tradeFee":0.00453300000000000000,
                 //                  "txUuid":"11f3850cc6214ea3b495adad3a032794",
                 //                  "dealPrice":0.15111300000000000000,
                 //                  "dealVolumePrice":4.53339000000000000000,
                 //                  "tradeType":"sell_market"
                 //              }
                 //          ],
                 //          "error_code":0,
                 //          "ts":1648509742164
                 //      }
                 //
                 std::any trades = this->safeList(response, std::string("data"),
                                                  ccxt::list{});
                 return this->parseTrades(trades, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name lbank#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see https://www.lbank.com/en-US/docs/index.html#query-all-orders
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOrders(std::any symbol = std::any{}, std::any since = std::any{},
              std::any limit = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 // default query is for canceled and completely filled orders
                 // does not return open orders unless specified explicitly
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " fetchOrders() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(isEqual(limit, std::any{}))) {
                   limit = 100;
                 }
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("current_page"), 1},
                     {std::string("page_length"), limit},
                 };
                 std::any response = awaitValue(
                     this->spotPrivatePostSupplementOrdersInfoHistory(
                         this->extend(request, params)));
                 //
                 //      {
                 //          "result":true,
                 //          "data":{
                 //              "total":1,
                 //              "page_length":100,
                 //              "orders":[
                 //                  {
                 //                      "cummulativeQuoteQty":0,
                 //                      "symbol":"doge_usdt",
                 //                      "executedQty":0,
                 //                      "orderId":"2cadc7cc-b5f6-486b-a5b4-d6ac49a9c186",
                 //                      "origQty":100,
                 //                      "price":0.05,
                 //                      "origQuoteOrderQty":5,
                 //                      "updateTime":1648501384000,
                 //                      "time":1648501363889,
                 //                      "type":"buy",
                 //                      "status":-1
                 //                  }, ...
                 //              ],
                 //              "current_page":1
                 //          },
                 //          "error_code":0,
                 //          "ts":1648505706348
                 //      }
                 //
                 std::any result = this->safeValue(
                     response, std::string("data"), ccxt::dict{});
                 std::any orders = this->safeList(result, std::string("orders"),
                                                  ccxt::list{});
                 return this->parseOrders(orders, market, since, limit);
               })
        .share();
  }

